import numpy as np

def sigmoid(z):
    return 1 / (1 + np.exp(-z))

def forward(X, W1, b1, W2, b2):
    h = sigmoid(X @ W1 + b1)
    return sigmoid(h @ W2 + b2)

W1 = np.array([[20., -20.], [20., -20.]])
b1 = np.array([-10., 30.])
W2 = np.array([[20.], [20.]])
b2 = np.array([-30.])
X = np.array([[0, 0], [0, 1], [1, 0], [1, 1]], dtype=float)
out = forward(X, W1, b1, W2, b2)
print(np.round(out).astype(int).ravel().tolist())

def count_params(sizes):
    return sum(n_in * n_out + n_out for n_in, n_out in zip(sizes[:-1], sizes[1:]))

print(count_params([4, 8, 3]))
print(count_params([784, 128, 10]))
